{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Reduce common history items' input contribution using fixed training-frequency scales, normalized over observed items and clipped to [0.75, 1.25]. Persist scales as checkpoint buffers; the generated predictor imports HSTURec and restores them automatically. Preserve candidate scoring, learned embeddings, HSTU topology, readout, loss and optimizer.",
      "edits": [
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)
        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)
        self.register_buffer("input_frequency_scale", torch.ones(itemnum + 1))
        self.input_frequency_scale[0] = 0.0
        self.pos_emb = nn.Embedding(maxlen + 1, hidden_units, padding_idx=0)"
        },
        {
          "find": "        seq_emb = self.item_emb(seq) * math.sqrt(self.hidden_units)
        observed = (seq != 0).long()",
          "replace": "        seq_emb = self.item_emb(seq) * math.sqrt(self.hidden_units)
        seq_emb = seq_emb * self.input_frequency_scale[seq].unsqueeze(-1)
        observed = (seq != 0).long()"
        },
        {
          "find": "    ).to(device)
    optimizer = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    ).to(device)
    training_counts = np.zeros(itemnum + 1, dtype=np.int64)
    for history in user_train.values():
        np.add.at(training_counts, np.asarray(history, dtype=np.int64), 1)
    training_counts[0] = 0
    observed_items = training_counts > 0
    frequency_scale = np.ones(itemnum + 1, dtype=np.float64)
    if observed_items.any():
        observed_scale = (1.0 + np.log1p(training_counts[observed_items].astype(np.float64))) ** (-0.25)
        observed_scale /= observed_scale.mean()
        frequency_scale[observed_items] = np.clip(observed_scale, 0.75, 1.25)
    frequency_scale[0] = 0.0
    with torch.no_grad():
        model.input_frequency_scale.copy_(torch.as_tensor(
            frequency_scale, dtype=model.input_frequency_scale.dtype, device=device
        ))
    optimizer = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
